  const uses = (profileId: string) => assignments.filter((assignment) => assignment.profile_ids.includes(profileId));
  return <section className="maintenance-section alerts-master-section"><div className="alerts-master-workspace"><div className="alerts-master-list"><div className="maintenance-table-wrap"><table className="maintenance-table alerts-master-table"><thead><tr><th>#</th><th>Profile ID</th><th>Title</th><th>Rules</th><th>Assignments</th></tr></thead><tbody>{profiles.map((profile, index) => <tr key={profile.id} className={profile.id === selected?.id ? "is-selected" : ""} onClick={() => selectProfile(profile)}><td>{index + 1}</td><td>{profile.id}</td><td>{profile.title || "—"}</td><td>{profile.rule_ids.length}</td><td>{uses(profile.id).length}</td></tr>)}{profiles.length === 0 && <tr><td colSpan={5} className="alerts-empty">No profiles. Add a profile to begin.</td></tr>}</tbody></table></div><div className="protocol-map-row-actions"><button type="button" className="maintenance-secondary-button button-with-icon" disabled={busy} onClick={newProfile}><Icon name="add" size={16} />Add profile</button></div></div><ProfileDetail profile={selected} draft={draft} editing={editing} rules={rules} metrics={metrics} assignments={selected ? uses(selected.id) : []} busy={busy} onEdit={() => { if (selected) { setDraft(copyProfile(selected)); setEditing(true); } }} onCancel={() => { if (selected) setDraft(copyProfile(selected)); setEditing(false); }} onSave={saveProfile} onDraft={setDraft} onToggleRule={toggleRule} onDelete={deleteProfile} /></div></section>;
