};

export function InterfaceDetailPane({
  item,
  metrics,
  alertRules,
  mode,
  onChangeMode,
  onMinimizeWidth,
  onRestoreWidth,
  onMaximizeWidth,
  isWidthMinimized,
  isWidthRestored,
